//#define S (2.-abs(p.x*sin(.2*p.z)+p.y*cos(.2*p.z)))
float s(vec3 p) {
    vec2 r = sin(.4*p.z+vec2(0,1.5707));
    p.yx*=mat2(r.y,-r.x,r.x,r.y);
    return min(5.-length(p.xy),max(3.-length(p.xy),2.-min(abs(p.x),abs(p.y))));
}
#define S s(p)
vec3 palette(float a) {
    return vec3(.5,.3,.4)+vec3(.1,.5,.5)*(.5+.5*sin(a+vec3(2,1,3)));
}
const float ms = .2;
void mainImage(out vec4 O,vec2 F) {
    vec3 p = vec3(0,0,iTime-30.), t = normalize(vec3(F-iResolution.xy*.5,iResolution.y*.4));
    for (float d;d<100.;d++)
    {
        p+=t*S*ms;
        O.r=d*ms;
        if (S<.001)
        {
            break;
        }
    }
    O.rgb=clamp(O.r*.1,0.,1.)*palette(pow(p.z-iTime+30.,.8)+iTime-30.+fract(p.z));
    O.a=1.;
    //if (F.y/iResolution.y<.1) O=vec4(palette(F.x/iResolution.x*8.),1);
}
